package com.drivique.api.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="payments",schema="billing",uniqueConstraints=@UniqueConstraint(name="uq_payments_gateway_reference",columnNames={"gateway_provider","gateway_reference"}))
public class Payment { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="contract_id",nullable=false) private RentalContract contract; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="payment_method_id",nullable=false) private PaymentMethod paymentMethod; @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="status_id",nullable=false) private PaymentStatus status; @Column(name="gateway_provider",nullable=false,length=30) private String gatewayProvider; @Column(name="gateway_reference",nullable=false,length=100) private String gatewayReference; @Column(nullable=false,precision=12,scale=2) private BigDecimal amount; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="currency_id",nullable=false) private Currency currency; @Column(name="paid_at") private Instant paidAt; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="confirmed_by_user_id") private User confirmedByUser; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now(); protected Payment(){} public Payment(RentalContract contract,PaymentMethod method,PaymentStatus status,String reference,BigDecimal amount,Currency currency){this(contract,method,status,"WOMPI",reference,amount,currency,null);} public Payment(RentalContract contract,PaymentMethod method,PaymentStatus status,String gatewayProvider,String reference,BigDecimal amount,Currency currency,User confirmedByUser){this.contract=contract;this.paymentMethod=method;this.status=status;this.gatewayProvider=gatewayProvider;this.gatewayReference=reference;this.amount=amount;this.currency=currency;this.confirmedByUser=confirmedByUser;} public UUID getId(){return id;} public RentalContract getContract(){return contract;} public PaymentMethod getPaymentMethod(){return paymentMethod;} public String getGatewayReference(){return gatewayReference;} public BigDecimal getAmount(){return amount;} public Currency getCurrency(){return currency;} public Instant getPaidAt(){return paidAt;} public PaymentStatus getStatus(){return status;} public void setStatus(PaymentStatus value){status=value;updatedAt=Instant.now();} public void setPaidAt(Instant value){paidAt=value;updatedAt=Instant.now();} }
